36	// Binary envelope identification. The format is interpreted from these bytes,
37	// never from the file name/extension.
38	//
39	//   magic     "ENVFILE1"  7 bytes, fixed identification
40	//   version   uint8      1 byte,  format version (1)
41	//   algorithm uint8      1 byte,  algorithm identifier (1 = AES-256-GCM)
42	//   nonce     12 bytes            fresh per encryption
43	//   ciphertext N bytes            raw input bytes encrypted (may be empty)
44	//   tag       16 bytes            GCM authentication tag
45	//
46	// Everything from the first magic byte through the last ciphertext byte is
47	// the authenticated data, so the header used to interpret the envelope cannot
48	// be tampered with without detection. Multi-byte integer fields are single
49	// bytes here, so there is no endianness to decode.
50	constexpr unsigned char kEnvelopeMagic[7] = {
51	    'E', 'N', 'V', 'F', 'I', 'L', 'E'};
52	constexpr std::size_t kEnvelopeMagicBytes = 7;
53	constexpr std::size_t kHeaderBytes =
54	    kEnvelopeMagicBytes + 1 + 1 + kNonceBytes;  // 21 bytes
55	constexpr unsigned char kEnvelopeVersion = 1;
56	constexpr unsigned char kAlgAes256Gcm = 1;
