58	// Owns raw key material and wipes it with OPENSSL_cleanse on every exit path.
59	class SecureBuffer {
60	public:
61	    SecureBuffer() = default;
62	    explicit SecureBuffer(std::size_t size) : size_(size) {
63	        data_ = new unsigned char[size_];
64	    }
65	    ~SecureBuffer() { wipe(); }
66	
67	    SecureBuffer(const SecureBuffer&) = delete;
68	    SecureBuffer& operator=(const SecureBuffer&) = delete;
69	    SecureBuffer(SecureBuffer&& other) noexcept
70	        : data_(other.data_), size_(other.size_) {
71	        other.data_ = nullptr;
72	        other.size_ = 0;
73	    }
74	    SecureBuffer& operator=(SecureBuffer&&) = delete;
75	
76	    unsigned char* data() { return data_; }
77	    std::size_t size() const { return size_; }
78	
79	    void wipe() {
80	        if (data_ != nullptr) {
81	            OPENSSL_cleanse(data_, size_);
82	            delete[] data_;
83	            data_ = nullptr;
84	            size_ = 0;
85	        }
86	    }
87	
88	private:
89	    unsigned char* data_ = nullptr;
90	    std::size_t size_ = 0;
91	};
