103	// Fills the buffer using OpenSSL's CSPRNG (backed by the operating system's
104	// secure random source). Never seeded from time, paths, or ordinary PRNGs.
105	bool generateKey(SecureBuffer& key, std::string& error) {
106	    if (RAND_bytes(key.data(), static_cast<int>(key.size())) != 1) {
107	        error = "secure random source failed";
108	        const std::string detail = opensslErrorString();
109	        if (!detail.empty()) {
110	            error += ": ";
111	            error += detail;
112	        }
113	        return false;
114	    }
115	    return true;
116	}
