123	// Why a save attempt ended the way it did. kSaved is the only success; every
124	// other status is reported to the user with an explanatory message. Shared by
125	// keygen's key file and encrypt's envelope file: apart from their permission
126	// policy their save pipeline is the same.
127	enum class SaveStatus {
128	    kSaved,          // all bytes written, fsynced, and closed; mode 0600
129	    kNotCreated,     // open() produced no file, so nothing had to be cleaned
130	    kCleanedUp,      // this run created the file, failed, and removed it
131	    kCleanupFailed,  // this run created the file, failed, and removal failed
132	};
133	
134	// Complete outcome of one output save attempt: whether it succeeded, why it
135	// failed when it did, and whether the file this run created was cleaned up.
136	// The save logic itself writes nothing to stdout or stderr; the command line
137	// reports error, and additionally reports removalWarning only when cleanup
138	// failed, so a failed removal can never mask the original save failure and a
139	// caller can tell "removed" apart from "could not remove" instead of inferring
140	// deletion from failure alone. Neither string ever contains key or plaintext
141	// material.
142	struct SaveResult {
143	    SaveStatus status = SaveStatus::kNotCreated;
144	    std::string error;           // why the save did not succeed; empty on success
145	    std::string removalWarning;  // populated only for kCleanupFailed
146	
147	    bool saved() const { return status == SaveStatus::kSaved; }
148	};
