150	// Owns the descriptor opened for the newly created output file for the
151	// duration of one save attempt and closes it exactly once. Closing is
152	// centralized here rather than spread across the failure branches: a branch
153	// only records its reason, and the descriptor is still released on every
154	// path out of scope.
155	class FdGuard {
156	public:
157	    FdGuard() = default;
158	    explicit FdGuard(int fd) : fd_(fd) {}
159	    ~FdGuard() { close(); }
160	
161	    FdGuard(const FdGuard&) = delete;
162	    FdGuard& operator=(const FdGuard&) = delete;
163	    FdGuard(FdGuard&&) = delete;
164	    FdGuard& operator=(FdGuard&&) = delete;
165	
166	    // Closes and disarms the guard, reporting close(2)'s status. Used after
167	    // fsync(), where a reported failure means durability could not be
168	    // confirmed and success must not be reported. Must be called while armed.
169	    int finish() {
170	        const int fd = fd_;
171	        fd_ = -1;
172	        return ::close(fd);
173	    }
174	
175	    // Best-effort close for failure paths: the save has already failed, and
176	    // close(2) releases the descriptor even when it reports an error, so the
177	    // result is intentionally discarded here. Idempotent via disarming.
178	    void close() {
179	        if (fd_ != -1) {
180	            const int fd = fd_;
181	            fd_ = -1;
182	            ::close(fd);
183	        }
184	    }
185	
186	private:
187	    int fd_ = -1;
188	};
