190	// Forces the freshly created file to exactly 0600: owner read/write, no
191	// execute bit, no group/other access. The mode given to open() is still
192	// reduced by the inherited process umask, which can strip owner read (umask
193	// 0400), owner write (umask 0200), or both (umask 0600); fchmod() is not
194	// affected by the umask.
195	//
196	// What happens next is the one permission difference the two outputs keep:
197	//
198	//   key files   - fchmod() is followed by an fstat() verification, and both
199	//                 must succeed with exactly 0600 before any key byte is
200	//                 written. A filesystem that silently keeps different
201	//                 permissions is a failure, not a success.
202	//   envelopes   - fchmod() alone must succeed; group/other never gain access
203	//                 at creation and the result is not re-verified.
204	//
205	// The distinction is the verifyPermissions parameter so the save pipeline
206	// stays shared.
207	bool forceOwnerOnlyPermissions(int fd, const std::string& path,
208	                               bool verifyPermissions,
209	                               const char* fileKind, std::string& error) {
210	    if (::fchmod(fd, S_IRUSR | S_IWUSR) != 0) {
211	        error = std::string("cannot set ") + fileKind +
212	                " file permissions to 0600 on '" + path + "': " +
213	                errnoDescription(errno);
214	        return false;
215	    }
216	    if (!verifyPermissions) {
217	        return true;
218	    }
219	    struct stat info;
220	    if (::fstat(fd, &info) != 0) {
221	        error = std::string("cannot verify ") + fileKind +
222	                " file permissions on '" + path + "': " +
223	                errnoDescription(errno);
224	        return false;
225	    }
226	    if ((info.st_mode & 0777) != (S_IRUSR | S_IWUSR)) {
227	        error = std::string("cannot guarantee ") + fileKind +
228	                " file permissions 0600 on '" + path + "'";
229	        return false;
230	    }
231	    return true;
232	}
