234	// Saves one freshly produced output blob to a brand new file. This is the
235	// single save pipeline shared by keygen (the 32 raw key bytes) and encrypt
236	// (the sealed envelope bytes); the only business difference between the two
237	// is the permission policy, selected by verifyPermissions (see above). The
238	// fileKind strings ("key"/"envelope") only build the existing diagnostic
239	// messages, and never contain file contents.
240	//
241	// Any existing path (file, empty file, directory, symlink including a
242	// dangling one) is rejected through O_CREAT|O_EXCL|O_NOFOLLOW before the
243	// target or its link is touched; the inherited umask cannot widen or narrow
244	// the mode away from 0600 because fchmod() sets it explicitly.
245	//
246	// The outcome is reported entirely through SaveResult: an open() failure
247	// creates nothing (kNotCreated); a failure after creation closes the
248	// descriptor via the FdGuard and removes this run's file, reporting either
249	// kCleanedUp or, if the removal itself failed, kCleanupFailed with the
250	// removal reason in removalWarning so the caller can warn that an incomplete
251	// file may remain. This function never writes to stdout or stderr.
252	SaveResult writeOutputFile(const std::string& path,
253	                           const unsigned char* bytes,
254	                           std::size_t byteCount, const char* fileKind,
255	                           bool verifyPermissions) {
256	    SaveResult result;
257	
258	    int fd = ::open(path.c_str(),
259	                    O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW,
260	                    S_IRUSR | S_IWUSR);
261	    if (fd == -1) {
262	        const int savedErrno = errno;
263	        // Pre-creation failure: nothing was created, so this must not enter
264	        // the "remove the new file" handling and an existing target's
265	        // content, permissions, and links are never touched.
266	        result.status = SaveStatus::kNotCreated;
267	        if (savedErrno == EEXIST || savedErrno == ELOOP) {
268	            result.error = "refusing to write, path already exists: " + path;
269	        } else {
270	            result.error = std::string("cannot create ") + fileKind +
271	                           " file '" + path + "': " +
272	                           errnoDescription(savedErrno);
273	        }
274	        return result;
275	    }
276	
277	    FdGuard guard(fd);
278	    result.status = SaveStatus::kCleanedUp;  // assumed until the save completes
279	    std::string error;
280	
281	    // If the permissions cannot be guaranteed, this run must not be reported
282	    // as a success even though the output was produced and the file was
283	    // created: skip the write and fall through to the cleanup below. For key
284	    // files this is strictly before the first key byte reaches the file.
285	    if (forceOwnerOnlyPermissions(fd, path, verifyPermissions, fileKind,
286	                                  error)) {
287	        std::size_t totalWritten = 0;
288	        while (totalWritten < byteCount) {
289	            ssize_t written =
290	                ::write(fd, bytes + totalWritten, byteCount - totalWritten);
291	            if (written < 0) {
292	                if (errno == EINTR) {
293	                    // Recoverable interrupt with no byte acknowledged: retry
294	                    // the same slice, so the content is neither lost nor
295	                    // duplicated.
296	                    continue;
297	                }
298	                error = std::string("failed writing ") + fileKind +
299	                        " file '" + path + "': " + errnoDescription(errno);
300	                break;
301	            }
302	            if (written == 0) {
303	                // Bytes were still pending but nothing was written: a save
304	                // failure, never an endless retry.
305	                error = std::string("failed writing ") + fileKind +
306	                        " file '" + path + "': short write";
307	                break;
308	            }
309	            totalWritten += static_cast<std::size_t>(written);
310	        }
311	
312	        if (totalWritten == byteCount) {
313	            if (::fsync(fd) != 0) {
314	                error = std::string("failed syncing ") + fileKind +
315	                        " file '" + path + "': " + errnoDescription(errno);
316	            } else if (guard.finish() != 0) {
317	                // The descriptor is closed by the kernel even when close
318	                // fails, but durability could not be confirmed: do not
319	                // report success.
320	                error = std::string("failed closing ") + fileKind +
321	                        " file '" + path + "': " + errnoDescription(errno);
322	            } else {
323	                // The complete original output is written, synced, and
324	                // closed; key files verified 0600 before the first byte.
325	                result.status = SaveStatus::kSaved;
326	                result.error.clear();
327	                return result;
328	            }
329	        }
330	    }
331	
332	    // Failure after creation. The descriptor opened by this run is closed
333	    // exactly once (guard.finish() above already disarmed it on the
334	    // close-failure path); removing the path cannot touch prior content
335	    // because O_EXCL guaranteed the file did not exist before open().
336	    guard.close();
337	    if (::unlink(path.c_str()) != 0 && errno != ENOENT) {
338	        // The original save failure remains the reported cause; this only
339	        // adds that the incomplete file could not be removed.
340	        result.status = SaveStatus::kCleanupFailed;
341	        result.removalWarning =
342	            std::string("could not remove partial ") + fileKind +
343	            " file '" + path + "': " + errnoDescription(errno);
344	    }
345	    result.error = std::move(error);
346	    return result;
347	}
