349	int runKeygen(int argc, char* argv[]) {
350	    std::string outputPath;
351	    bool haveOutput = false;
352	
353	    for (int i = 2; i < argc; ++i) {
354	        std::string_view arg(argv[i]);
355	        if (arg == "--output") {
356	            if (haveOutput) {
357	                std::cerr << "envelopefile: '--output' specified more than "
358	                             "once\n"
359	                          << kKeygenUsage;
360	                return 2;
361	            }
362	            if (i + 1 >= argc) {
363	                std::cerr << "envelopefile: option '--output' requires a "
364	                             "non-empty path\n"
365	                          << kKeygenUsage;
366	                return 2;
367	            }
368	            outputPath = argv[++i];
369	            if (outputPath.empty()) {
370	                std::cerr << "envelopefile: option '--output' requires a "
371	                             "non-empty path\n"
372	                          << kKeygenUsage;
373	                return 2;
374	            }
375	            haveOutput = true;
376	        } else {
377	            std::cerr << "envelopefile: unsupported argument: '" << arg
378	                      << "'\n"
379	                      << kKeygenUsage;
380	            return 2;
381	        }
382	    }
383	
384	    if (!haveOutput) {
385	        std::cerr << "envelopefile: missing required option '--output'\n"
386	                  << kKeygenUsage;
387	        return 2;
388	    }
389	
390	    SecureBuffer key(kKeyBytes);
391	    std::string error;
392	    if (!generateKey(key, error)) {
393	        std::cerr << "envelopefile: " << error << '\n';
394	        return 1;
395	    }
396	
397	    // Key files get the strict policy: fchmod() plus an fstat() check that
398	    // the mode is exactly 0600, all before the first key byte is written.
399	    const SaveResult save = writeOutputFile(outputPath, key.data(), key.size(),
400	                                            "key", /*verifyPermissions=*/true);
401	    if (!save.saved()) {
402	        // The save logic reports outcomes as data; the command line owns all
403	        // user-facing messages. The original failure is always the primary
404	        // cause; a failed cleanup is reported only as an additional warning,
405	        // never as a replacement, so the exit code stays 1 and the user can
406	        // tell that an incomplete key file may remain.
407	        std::cerr << "envelopefile: " << save.error << '\n';
408	        if (save.status == SaveStatus::kCleanupFailed) {
409	            std::cerr << "envelopefile: warning: " << save.removalWarning
410	                      << '\n';
411	        }
412	        return 1;
413	    }
414	
415	    // key is wiped here by the SecureBuffer destructor; its contents never
416	    // reach stdout, stderr, or any log.
417	    std::cout << "envelopefile: 32-byte key generated and saved to '"
418	              << outputPath << "'\n";
419	    return 0;
420	}
