422	// ---------------------------------------------------------------------------
423	// encrypt
424	// ---------------------------------------------------------------------------
425	
426	// Reads an entire file as raw bytes. The bytes are returned without any
427	// newline/NUL conversion; an empty file yields an empty vector. The path is
428	// never followed through a terminal symlink for the *output*, but key and
429	// input paths are opened normally (a symlink key/input is a legitimate file).
430	bool readAllBytes(const std::string& path, std::vector<unsigned char>& out,
431	                  std::string& error, const char* what) {
432	    int fd = ::open(path.c_str(), O_RDONLY);
433	    if (fd == -1) {
434	        error = std::string("cannot read ") + what + " '" + path + "': " +
435	                errnoDescription(errno);
436	        return false;
437	    }
438	    FdGuard guard(fd);
439	
440	    out.clear();
441	    unsigned char chunk[4096];
442	    for (;;) {
443	        ssize_t got = ::read(fd, chunk, sizeof(chunk));
444	        if (got < 0) {
445	            if (errno == EINTR) {
446	                continue;
447	            }
448	            error = std::string("failed reading ") + what + " '" + path +
449	                    "': " + errnoDescription(errno);
450	            return false;
451	        }
452	        if (got == 0) {
453	            break;  // end of file
454	        }
455	        out.insert(out.end(), chunk, chunk + static_cast<std::size_t>(got));
456	    }
457	    return true;
458	}
459	
460	// Reads exactly kKeyBytes (32) raw bytes from the key file: no trailing data,
461	// no text decoding, no substitute key. A short or long file is an error.
462	bool readKeyFile(const std::string& path, SecureBuffer& key,
463	                 std::string& error) {
464	    int fd = ::open(path.c_str(), O_RDONLY);
465	    if (fd == -1) {
466	        error = "cannot read key file '" + path + "': " +
467	                errnoDescription(errno);
468	        return false;
469	    }
470	    FdGuard guard(fd);
471	
472	    std::size_t total = 0;
473	    while (total < kKeyBytes) {
474	        ssize_t got = ::read(fd, key.data() + total, kKeyBytes - total);
475	        if (got < 0) {
476	            if (errno == EINTR) {
477	                continue;
478	            }
479	            error = "failed reading key file '" + path + "': " +
480	                    errnoDescription(errno);
481	            return false;
482	        }
483	        if (got == 0) {
484	            error = "key file '" + path + "' is " +
485	                    std::to_string(total) + " bytes, expected exactly " +
486	                    std::to_string(kKeyBytes);
487	            return false;
488	        }
489	        total += static_cast<std::size_t>(got);
490	    }
491	
492	    // The file must contain exactly the key, nothing after it.
493	    unsigned char extra;
494	    ssize_t got;
495	    do {
496	        got = ::read(fd, &extra, 1);
497	    } while (got < 0 && errno == EINTR);
498	    if (got < 0) {
499	        error = "failed reading key file '" + path + "': " +
500	                errnoDescription(errno);
501	        return false;
502	    }
503	    if (got > 0) {
504	        error = "key file '" + path + "' is longer than " +
505	                std::to_string(kKeyBytes) +
506	                " bytes; expected exactly 32 raw key bytes";
507	        return false;
508	    }
509	    return true;
510	}
511	
512	// Seals plaintext with AES-256-GCM and builds the complete envelope. The
513	// header (magic/version/algorithm/nonce) is supplied as authenticated data so
514	// the bytes used to interpret the envelope are covered by the tag. On success
515	// envelope holds header || ciphertext || tag; on failure it returns false and
516	// sets error, without ever generating a substitute key.
517	bool sealEnvelope(const unsigned char* key,
518	                  const std::vector<unsigned char>& plaintext,
519	                  std::vector<unsigned char>& envelope,
520	                  std::string& error) {
521	    unsigned char nonce[kNonceBytes];
522	    if (RAND_bytes(nonce, static_cast<int>(kNonceBytes)) != 1) {
523	        error = "secure random source failed";
524	        const std::string detail = opensslErrorString();
525	        if (!detail.empty()) {
526	            error += ": ";
527	            error += detail;
528	        }
529	        OPENSSL_cleanse(nonce, sizeof(nonce));
530	        return false;
531	    }
532	
533	    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
534	    if (ctx == nullptr) {
535	        error = "cannot initialize AES-256-GCM";
536	        OPENSSL_cleanse(nonce, sizeof(nonce));
537	        return false;
538	    }
539	
540	    int outLen = 0;
541	    const std::size_t bodySize = plaintext.size();
542	    envelope.resize(kHeaderBytes + bodySize + kTagBytes);
543	    unsigned char* body = envelope.data() + kHeaderBytes;
544	    unsigned char* tag = body + bodySize;
545	
546	    auto fail = [&](const std::string& message) {
547	        error = message;
548	        EVP_CIPHER_CTX_free(ctx);
549	        OPENSSL_cleanse(nonce, sizeof(nonce));
550	        // Do not leave partial ciphertext in the caller's buffer.
551	        if (!envelope.empty()) {
552	            OPENSSL_cleanse(envelope.data(), envelope.size());
553	        }
554	        envelope.clear();
555	    };
556	
557	    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, nullptr,
558	                           nullptr) != 1) {
559	        fail("AES-256-GCM initialization failed");
560	        return false;
561	    }
562	    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN,
563	                            static_cast<int>(kNonceBytes), nullptr) != 1) {
564	        fail("cannot set GCM nonce length");
565	        return false;
566	    }
567	    if (EVP_EncryptInit_ex(ctx, nullptr, nullptr, key, nonce) != 1) {
568	        fail("cannot set GCM key and nonce");
569	        return false;
570	    }
571	
572	    // Build the header first and authenticate it before any plaintext byte,
573	    // so magic/version/algorithm/nonce are all bound to the tag. A null output
574	    // marks these bytes as additional authenticated data; OpenSSL reports the
575	    // AAD length back, so use a dedicated counter for ciphertext below rather
576	    // than reusing this one (it would otherwise spoil the empty-input check).
577	    unsigned char* header = envelope.data();
578	    std::memcpy(header, kEnvelopeMagic, kEnvelopeMagicBytes);
579	    header[kEnvelopeMagicBytes] = kEnvelopeVersion;
580	    header[kEnvelopeMagicBytes + 1] = kAlgAes256Gcm;
581	    std::memcpy(header + kEnvelopeMagicBytes + 2, nonce, kNonceBytes);
582	
583	    if (EVP_EncryptUpdate(ctx, nullptr, &outLen, header,
584	                          static_cast<int>(kHeaderBytes)) != 1) {
585	        fail("cannot authenticate envelope header");
586	        return false;
587	    }
588	
589	    int ciphertextLen = 0;
590	    if (!plaintext.empty()) {
591	        if (EVP_EncryptUpdate(ctx, body, &ciphertextLen, plaintext.data(),
592	                              static_cast<int>(plaintext.size())) != 1) {
593	            fail("encryption failed");
594	            return false;
595	        }
596	    }
597	    int finalLen = 0;
598	    if (EVP_EncryptFinal_ex(ctx, body + ciphertextLen, &finalLen) != 1) {
599	        fail("encryption finalization failed");
600	        return false;
601	    }
602	    if (static_cast<std::size_t>(ciphertextLen) +
603	            static_cast<std::size_t>(finalLen) !=
604	        bodySize) {
605	        fail("ciphertext length mismatch");
606	        return false;
607	    }
608	    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG,
609	                            static_cast<int>(kTagBytes), tag) != 1) {
610	        fail("cannot obtain authentication tag");
611	        return false;
612	    }
613	
614	    EVP_CIPHER_CTX_free(ctx);
615	    OPENSSL_cleanse(nonce, sizeof(nonce));
616	    return true;
617	}
618	
619	int runEncrypt(int argc, char* argv[]) {
620	    std::string keyPath;
621	    std::string inputPath;
622	    std::string outputPath;
623	    bool haveKey = false;
624	    bool haveInput = false;
625	    bool haveOutput = false;
626	
627	    // All-or-nothing parse: validate the whole argument list and reject the
628	    // entire operation (exit 2) before any file is read or created.
629	    for (int i = 2; i < argc; ++i) {
630	        std::string_view arg(argv[i]);
631	        std::string_view option;
632	        std::string* target = nullptr;
633	        bool* seen = nullptr;
634	
635	        if (arg == "--key") {
636	            option = "--key";
637	            target = &keyPath;
638	            seen = &haveKey;
639	        } else if (arg == "--input") {
640	            option = "--input";
641	            target = &inputPath;
642	            seen = &haveInput;
643	        } else if (arg == "--output") {
644	            option = "--output";
645	            target = &outputPath;
646	            seen = &haveOutput;
647	        } else {
648	            std::cerr << "envelopefile: unsupported argument: '" << arg
649	                      << "'\n"
650	                      << kEncryptUsage;
651	            return 2;
652	        }
653	
654	        if (*seen) {
655	            std::cerr << "envelopefile: '" << option
656	                      << "' specified more than once\n"
657	                      << kEncryptUsage;
658	            return 2;
659	        }
660	        if (i + 1 >= argc) {
661	            std::cerr << "envelopefile: option '" << option
662	                      << "' requires a non-empty path\n"
663	                      << kEncryptUsage;
664	            return 2;
665	        }
666	        *target = argv[++i];
667	        if (target->empty()) {
668	            std::cerr << "envelopefile: option '" << option
669	                      << "' requires a non-empty path\n"
670	                      << kEncryptUsage;
671	            return 2;
672	        }
673	        *seen = true;
674	    }
675	
676	    if (!haveKey || !haveInput || !haveOutput) {
677	        if (!haveKey) {
678	            std::cerr << "envelopefile: missing required option '--key'\n"
679	                      << kEncryptUsage;
680	        } else if (!haveInput) {
681	            std::cerr << "envelopefile: missing required option '--input'\n"
682	                      << kEncryptUsage;
683	        } else {
684	            std::cerr << "envelopefile: missing required option '--output'\n"
685	                      << kEncryptUsage;
686	        }
687	        return 2;
688	    }
689	
690	    // Read the exact 32-byte raw key. This buffer is wiped on every exit
691	    // path (success or failure), so the key never survives the operation in
692	    // memory and never reaches stdout/stderr.
693	    SecureBuffer key(kKeyBytes);
694	    {
695	        std::string error;
696	        if (!readKeyFile(keyPath, key, error)) {
697	            std::cerr << "envelopefile: " << error << '\n';
698	            return 1;
699	        }
700	    }
701	
702	    // Read the input as raw bytes (no conversion; empty input is allowed).
703	    std::vector<unsigned char> plaintext;
704	    {
705	        std::string error;
706	        if (!readAllBytes(inputPath, plaintext, error, "input file")) {
707	            std::cerr << "envelopefile: " << error << '\n';
708	            return 1;
709	        }
710	    }
711	
712	    // Seal with a fresh random nonce and an authenticated header.
713	    std::vector<unsigned char> envelope;
714	    {
715	        std::string error;
716	        if (!sealEnvelope(key.data(), plaintext, envelope, error)) {
717	            std::cerr << "envelopefile: " << error << '\n';
718	            return 1;
719	        }
720	    }
721	
722	    // Save to a brand new path with the shared pipeline; any existing path,
723	    // including the input or key path itself, is rejected before it is
724	    // touched. The envelope keeps the lighter permission policy: fchmod()
725	    // must succeed, but the key file's fstat() verification is not performed.
726	    const SaveResult save = writeOutputFile(
727	        outputPath, envelope.data(), envelope.size(), "envelope",
728	        /*verifyPermissions=*/false);
729	    if (!save.saved()) {
730	        std::cerr << "envelopefile: " << save.error << '\n';
731	        if (save.status == SaveStatus::kCleanupFailed) {
732	            std::cerr << "envelopefile: warning: " << save.removalWarning
733	                      << '\n';
734	        }
735	        return 1;
736	    }
737	
738	    // The original input and key files are never opened for writing, so
739	    // their contents and permissions are unchanged. The key is wiped by the
740	    // SecureBuffer destructor as this scope exits.
741	    std::cout << "envelopefile: file encrypted and envelope saved to '"
742	              << outputPath << "'\n";
743	    return 0;
744	}
745	
746	}  // namespace
747	
748	int main(int argc, char* argv[]) {
749	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
750	        std::cout << kVersionString;
751	        return 0;
752	    }
753	
754	    if (argc >= 2 && std::string_view(argv[1]) == "keygen") {
755	        return runKeygen(argc, argv);
756	    }
757	
758	    if (argc >= 2 && std::string_view(argv[1]) == "encrypt") {
759	        return runEncrypt(argc, argv);
760	    }
761	
762	    std::cerr << kUsage;
763	    return 2;
764	}
