383	    // Pre-creation refusal: fail WITHOUT calling the real open(), so the file
384	    // is provably never created (there is no descriptor and nothing on disk),
385	    // exercising the product's "open() produced no file" branch rather than
386	    // its post-creation cleanup. Matching only the O_CREAT|O_EXCL key open
387	    // keeps every other open (logs, stdio) untouched.
388	    if ((flags & O_CREAT) != 0 && (flags & O_EXCL) != 0 &&
389	        path != nullptr && isKeyPath(path) &&
390	        envFlagSet("EF_TEST_FAIL_OPEN")) {
391	        int injectedErrno = EACCES;
392	        const char* raw = std::getenv("EF_TEST_OPEN_ERRNO");
393	        if (raw != nullptr && raw[0] != '\0') {
394	            char* end = nullptr;
395	            const long requested = std::strtol(raw, &end, 10);
396	            if (end != raw && *end == '\0' && requested > 0) {
397	                injectedErrno = static_cast<int>(requested);
398	            }
399	        }
400	        errno = injectedErrno;
401	        return -1;
402	    }
403	    int fd = __real_open(path, flags, mode);
404	    if (fd != -1 && (flags & O_CREAT) != 0 && (flags & O_EXCL) != 0 &&
405	        isKeyPath(path)) {
406	        g_keyFd = fd;
407	        setKeyPath(path);
408	        resetWriteBookkeeping();
409	    }
410	    return fd;
411	}
412	
413	int __wrap_fchmod(int fd, mode_t mode) {
414	    if (isKeyFd(fd) && envFlagSet("EF_TEST_FAIL_FCHMOD")) {
415	        errno = EPERM;
416	        return -1;
417	    }
418	    return __real_fchmod(fd, mode);
419	}
420	
421	int __wrap_fstat(int fd, struct stat* info) {
422	    if (!isKeyFd(fd)) {
423	        return __real_fstat(fd, info);
424	    }
425	    // This is the post-fchmod verification read: fchmod itself already
426	    // reported success for the key fd when the code reaches fstat.
427	    if (envFlagSet("EF_TEST_FAIL_FSTAT")) {
428	        errno = EIO;
429	        return -1;
430	    }
431	    const int result = __real_fstat(fd, info);
432	    if (result == 0) {
433	        const char* forced = std::getenv("EF_TEST_FSTAT_MODE");
434	        if (forced != nullptr && forced[0] != '\0') {
435	            char* end = nullptr;
436	            const unsigned long forcedMode = std::strtoul(forced, &end, 8);
437	            if (end != forced && *end == '\0') {
438	                // Keep the file-type bits; replace only the permission bits
439	                // the product code verifies against exactly 0600.
440	                info->st_mode =
441	                    (info->st_mode & static_cast<mode_t>(~07777)) |
442	                    (static_cast<mode_t>(forcedMode) & 07777);
443	            }
444	        }
445	    }
446	    return result;
447	}
448	
449	ssize_t __wrap_write(int fd, const void* buffer, size_t count) {
450	    if (!isKeyFd(fd)) {
451	        return __real_write(fd, buffer, count);
452	    }
453	
454	    verifyIncomingBuffer(buffer, count);
455	
456	    const size_t requested = count;  // caller's original length for the log
457	    ScriptedCall call;
458	    const bool scripted = nextScriptedCall(call);
459	    if (scripted) {
460	        switch (call.outcome) {
461	            case WriteOutcome::kEintr:
462	                logCall(g_progress, requested, -1, EINTR);
463	                errno = EINTR;
464	                return -1;
465	            case WriteOutcome::kEio:
466	                logCall(g_progress, requested, -1, EIO);
467	                errno = EIO;
468	                return -1;
469	            case WriteOutcome::kZero:
470	                logCall(g_progress, requested, 0, 0);
471	                errno = 0;
472	                return 0;
473	            case WriteOutcome::kShort:
474	                if (count > static_cast<size_t>(call.limit)) {
475	                    count = static_cast<size_t>(call.limit);
476	                }
477	                break;
478	            case WriteOutcome::kPass:
479	                break;
480	        }
481	    } else {
482	        // Legacy single-knob injection, kept for the existing regressions.
483	        if (envFlagSet("EF_TEST_FAIL_WRITE")) {
484	            logCall(g_progress, requested, -1, EIO);
485	            errno = EIO;
486	            return -1;
487	        }
488	        const char* chunk = std::getenv("EF_TEST_PARTIAL_WRITE");
489	        if (chunk != nullptr) {
490	            const long limit = std::atol(chunk);
491	            if (limit > 0 && count > static_cast<size_t>(limit)) {
492	                count = static_cast<size_t>(limit);
493	            }
494	        }
495	    }
496	
497	    ssize_t result = __real_write(fd, buffer, count);
498	    logCall(g_progress, requested, result, errno);
499	    if (result > 0) {
500	        g_progress += static_cast<std::size_t>(result);
501	    }
502	    return result;
503	}
504	
505	int __wrap_fsync(int fd) {
506	    if (isKeyFd(fd) && envFlagSet("EF_TEST_FAIL_FSYNC")) {
507	        errno = EIO;
508	        return -1;
509	    }
510	    return __real_fsync(fd);
511	}
512	
513	int __wrap_close(int fd) {
514	    const bool wasKeyFd = isKeyFd(fd);
515	    const int result = __real_close(fd);
516	    if (wasKeyFd) {
517	        g_keyFd = -1;
518	        if (envFlagSet("EF_TEST_FAIL_CLOSE")) {
519	            // The descriptor is already closed for real; only the reported
520	            // status is faked, mirroring a genuine close(2) failure.
521	            errno = EIO;
522	            return -1;
523	        }
524	    }
525	    return result;
526	}
527	
528	int __wrap_unlink(const char* path) {
529	    // Only the cleanup of the file this run created can be faulted, so a
530	    // simulated failure never blocks removal of (or any operation on) an
531	    // unrelated path — the product code only ever unlinks the O_EXCL-created
532	    // key path, and this matches the injection to exactly that name.
533	    if (path != nullptr && g_keyPath[0] != '\0' &&
534	        std::strcmp(path, g_keyPath) == 0 &&
535	        envFlagSet("EF_TEST_FAIL_UNLINK")) {
536	        errno = EIO;
537	        return -1;
538	    }
539	    return __real_unlink(path);
540	}
541	
542	int __wrap_RAND_bytes(unsigned char* buf, int num) {
543	    if (!envFlagSet("EF_TEST_FAIL_RAND")) {
544	        const int result = __real_RAND_bytes(buf, num);
545	        if (result == 1) {
546	            g_randBuf = buf;
547	            g_randBufSize = num;
548	            char line[96];
549	            std::snprintf(line, sizeof(line),
550	                          "RAND %d partial=0 result=ok", num);
551	            logKeyLine(line);
552	        }
553	        return result;
554	    }
555	
556	    g_randBuf = buf;
557	    g_randBufSize = num;
558	
559	    // Simulate a CSPRNG that wrote some bytes before dying: the caller must
560	    // not mistake the partial fill for a valid key.
561	    long partial = 0;
562	    const char* raw = std::getenv("EF_TEST_RAND_PARTIAL");
563	    if (raw != nullptr) {
564	        partial = std::atol(raw);
565	        if (partial < 0) {
566	            partial = 0;
567	        }
568	        if (partial > num) {
569	            partial = num;
570	        }
571	    }
572	    for (long i = 0; i < partial; ++i) {
573	        buf[i] = 0xA5;
574	    }
575	
576	    // Start from an empty error queue, then optionally leave a descriptive
577	    // OpenSSL error so the "detail" and "no detail" messages are both
578	    // exercised deterministically.
579	    ERR_clear_error();
580	    if (envFlagSet("EF_TEST_RAND_ERROR_DETAIL")) {
581	#if OPENSSL_VERSION_NUMBER >= 0x30000000L
582	        ERR_raise(ERR_LIB_RAND, 0x7f);
583	#else
584	        ERR_put_error(ERR_LIB_RAND, 0, 0x7f, __FILE__, __LINE__);
585	#endif
586	    }
587	
588	    char line[96];
589	    std::snprintf(line, sizeof(line), "RAND %d partial=%ld result=fail",
590	                  num, partial);
591	    logKeyLine(line);
592	    return 0;
593	}
594	
595	void __wrap_OPENSSL_cleanse(void* ptr, size_t len) {
596	    if (ptr != nullptr && ptr == g_randBuf) {
597	        char line[96];
598	        std::snprintf(line, sizeof(line), "CLEANSED-KEY %zu", len);
599	        logKeyLine(line);
600	        // Record how far the save had progressed when the wipe happened, so
601	        // the test driver can prove a successful save was not preceded by
602	        // the wipe (which would have saved wiped data).
603	        char state[96];
604	        std::snprintf(state, sizeof(state),
605	                      "CLEANSE-STATE writes=%zu keyfd=%s",
606	                      g_progress, g_keyFd == -1 ? "closed" : "open");
607	        logKeyLine(state);
608	        // The buffer is about to be released; do not match a stale address.
609	        g_randBuf = nullptr;
610	        g_randBufSize = 0;
611	    }
612	    __real_OPENSSL_cleanse(ptr, len);
613	}
614	
615	}  // extern "C"
